-- Remove the demonstration sample data for good, then the isSample flags.
-- Everything flagged isSample was generated by the dev seed (fictional
-- "Sample Artist" profiles, generated artwork, placeholder videos and news),
-- never real content. Real rows are untouched.

-- 1. Site Settings: drop references to sample media, editions and honorees.
CREATE TEMP TABLE _sample_media AS SELECT id FROM "Media" WHERE "isSample";
CREATE TEMP TABLE _sample_edition AS SELECT id FROM "AwardEdition" WHERE "isSample";
CREATE TEMP TABLE _gone_nominee AS
  SELECT n.id FROM "Nominee" n
  JOIN "AwardCategory" c ON c.id = n."categoryId"
  JOIN "Artist" a ON a.id = n."artistId"
  WHERE n."isSample" OR c."isSample" OR a."isSample" OR c."editionId" IN (SELECT id FROM _sample_edition);

UPDATE "SiteSettings" s SET
  "branding" = CASE WHEN s."branding"->>'logoId' IN (SELECT id FROM _sample_media) THEN jsonb_set(s."branding", '{logoId}', 'null') ELSE s."branding" END,
  "hero" = jsonb_set(
    CASE WHEN s."hero"->>'posterId' IN (SELECT id FROM _sample_media) THEN jsonb_set(s."hero", '{posterId}', 'null') ELSE s."hero" END,
    '{videoId}',
    CASE WHEN s."hero"->>'videoId' IN (SELECT id FROM _sample_media) THEN 'null'::jsonb ELSE COALESCE(s."hero"->'videoId', 'null'::jsonb) END),
  "seo" = CASE WHEN s."seo"->>'ogImageId' IN (SELECT id FROM _sample_media) THEN jsonb_set(s."seo", '{ogImageId}', 'null') ELSE s."seo" END,
  "sponsors" = COALESCE((SELECT jsonb_agg(x) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(s."sponsors") = 'array' THEN s."sponsors" ELSE '[]'::jsonb END) x
                         WHERE COALESCE(x->>'logoId', '') NOT IN (SELECT id FROM _sample_media)), '[]'::jsonb),
  "featured" = jsonb_set(
    CASE WHEN jsonb_typeof(s."featured") = 'object' THEN s."featured" ELSE '{"nomineeIds":[],"artistIds":[]}'::jsonb END,
    '{nomineeIds}',
    COALESCE((SELECT jsonb_agg(x) FROM jsonb_array_elements_text(COALESCE(s."featured"->'nomineeIds', '[]'::jsonb)) x
              WHERE x NOT IN (SELECT id FROM _gone_nominee)), '[]'::jsonb)),
  "currentEditionId" = CASE WHEN s."currentEditionId" IN (SELECT id FROM _sample_edition) THEN NULL ELSE s."currentEditionId" END;

-- Featured artist ids pointing at sample artists.
UPDATE "SiteSettings" s SET "featured" = jsonb_set(s."featured", '{artistIds}',
  COALESCE((SELECT jsonb_agg(x) FROM jsonb_array_elements_text(COALESCE(s."featured"->'artistIds', '[]'::jsonb)) x
            WHERE x NOT IN (SELECT id FROM "Artist" WHERE "isSample")), '[]'::jsonb));

-- 2. Rows (children cascade: categories, honorees, album items, video links).
DELETE FROM "Nominee" WHERE id IN (SELECT id FROM _gone_nominee);
DELETE FROM "AwardCategory" WHERE "isSample" OR "editionId" IN (SELECT id FROM _sample_edition);
DELETE FROM "AwardEdition" WHERE "isSample";
DELETE FROM "Artist" WHERE "isSample";
DELETE FROM "Video" WHERE "isSample";
DELETE FROM "Album" WHERE "isSample";
DELETE FROM "NewsPost" WHERE "isSample";
DELETE FROM "Media" WHERE "isSample";
DELETE FROM "user" WHERE "isSample" AND role <> 'SUPER_ADMIN';

DROP TABLE _sample_media, _sample_edition, _gone_nominee;

-- 3. The flags themselves.
ALTER TABLE "user" DROP COLUMN "isSample";
ALTER TABLE "Media" DROP COLUMN "isSample";
ALTER TABLE "Artist" DROP COLUMN "isSample";
ALTER TABLE "AwardEdition" DROP COLUMN "isSample";
ALTER TABLE "AwardCategory" DROP COLUMN "isSample";
ALTER TABLE "Nominee" DROP COLUMN "isSample";
ALTER TABLE "Video" DROP COLUMN "isSample";
ALTER TABLE "Album" DROP COLUMN "isSample";
ALTER TABLE "NewsPost" DROP COLUMN "isSample";
